var t=`1151-montreal-smoked-meat-sandwich`;var r=`world-1151`;var n=`CA`;var a=`northern-america`;var s=4;var d=38;var o={en:`Montreal Smoked Meat Sandwich`,ua:`Сендвіч із копченим м'ясом по-монреальськи`};var l={en:`Montreal Smoked Meat Sandwich is a dish from Canada prepared with corned beef, rye bread, fermented cucumber, yellow mustard. This is a home-scale version with measured ingredients in the individual steps where they are used. Corned beef replaces traditionally cured AND smoked Montréal brisket; this is a sandwich-inspired adaptation, not authentic smoked meat.`,ua:`Сендвіч із копченим м'ясом по-монреальськи, страва кухні країни Канада, яку готують із таких продуктів: солонина, житній хліб, квашений огірок, жовта гірчиця. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Солонина замінює традиційно засолений ТА копчений монреальський брискет; це адаптація сендвіча, а не автентичне копчене м’ясо.`};var c=[{en:`Poach the listed ingredients in barely simmering liquid for about 25 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 25 хвилин до готовності й м’якості.`,t:[`poaching`],m:25,i:[[`corned-beef`,750,`g`],[`water`,750,`ml`],[`ground-black-pepper`,5,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`rye-bread`,8,`slice`],[`fermented-cucumber`,140,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`yellow-mustard`,65,`g`],[`swiss-cheese`,140,`g`]]}];var h={slug:t,id:r,country:`CA`,region:a,servings:4,minutes:38,title:o,text:l,steps:c};export{n as country,h as default,r as id,d as minutes,a as region,s as servings,t as slug,c as steps,l as text,o as title};